 #include "nsCharsetConverterManager.h"

-// Class nsCharsetConverterManager [implementation]
+#include "../base/src/nsMsgI18N.h"
+#include "mozilla/intl/EncodingToLang.h"
+#include "nsICharsetConverterManager.h"
+#include "nsString.h"
